interface Node {
  operation(): number
}

class Leaf implements Node {
  constructor(private value: number) {}
  operation() { return this.value }
}

class Folder implements Node {
  private children: Node[] = []
  add(c: Node) { this.children.push(c) }
  operation() { return this.children.reduce((s, c) => s + c.operation(), 0) }
}

interface FSNode { size(): number }

class File implements FSNode {
  constructor(private bytes: number) {}
  size() { return this.bytes }
}

class Directory implements FSNode {
  constructor(public children: FSNode[] = []) {}
  size() { return this.children.reduce((s, c) => s + c.size(), 0) }
}

// Version A
class Node {
  name: string
  children?: Node[]
  constructor(name: string) { this.name = name }
  add(child: Node) { if (!this.children) this.children = []; this.children.push(child) }
  value(): number { return (this.children || []).reduce((s, c) => s + c.value(), 0) }
}

// Version B
interface TreeNode { value(): number }
class Leaf implements TreeNode { constructor(private v: number) {}
  value() { return this.v }
}
class Branch implements TreeNode { constructor(public children: TreeNode[] = []) {}
  add(c: TreeNode) { this.children.push(c) }
  value() { return this.children.reduce((s, c) => s + c.value(), 0) }
}
